g = 9.80665
# Mean accelerometer reading (in g) with each axis pointing up (+1 g true) and down (-1 g true)
a_up   = np.array([+1.020, +1.004, +0.998])   # x, y, z
a_down = np.array([-0.980, -1.006, -1.002])
bias  = (a_up + a_down) / 2
scale = (a_up - a_down) / 2 - 1                # fractional error, with g = 1
print("accel bias (g):", bias, " scale error:", scale)

# Gyro bias and noise from a stationary record (deg/s), shape (N, 3)
rng = np.random.default_rng(1)
gyro = np.array([0.08, -0.03, 0.05]) + 0.011 * rng.standard_normal((30_000, 3))
print("gyro bias (deg/s):", gyro.mean(axis=0), " noise (deg/s):", gyro.std(axis=0))', 'Run on 30 s of stationary pad data before arming', 0);

def qmul(a, b):
    w1, x1, y1, z1 = a; w2, x2, y2, z2 = b
    return np.array([w1*w2 - x1*x2 - y1*y2 - z1*z2,
                     w1*x2 + x1*w2 + y1*z2 - z1*y2,
                     w1*y2 - x1*z2 + y1*w2 + z1*x2,
                     w1*z2 + x1*y2 - y1*x2 + z1*w2])

def step(q, gyro_rad, dt):
    """Integrate body rates (rad/s) one step; returns a unit quaternion."""
    q = q + 0.5 * qmul(q, np.array([0.0, *gyro_rad])) * dt
    return q / np.linalg.norm(q)

# Only trust the accelerometer for tilt when |specific force| is close to 1 g (not during boost)
def trust_accel(a_g, tol=0.1):
    return abs(np.linalg.norm(a_g) - 1.0) < tol

q = np.array([1.0, 0, 0, 0])
for _ in range(250):                               # 0.25 s of 360 deg/s roll at 1 kHz
    q = step(q, np.radians([360.0, 0, 0]), 0.001)
print("roll after 0.25 s (deg):", np.degrees(2 * np.arctan2(q[1], q[0])))   # about 90', 'Switch tilt correction off while the specific force is far from 1 g', 1);
from scipy.signal import welch

fs = 10_000
x = np.random.default_rng(0).standard_normal(120_000) * 10.0   # 12 s, about 10 g rms, white
f, pxx = welch(x, fs=fs, nperseg=4096, noverlap=2048)           # g^2/Hz
band = (f >= 20) & (f <= 2000)
grms = np.sqrt(np.trapezoid(pxx[band], f[band]))
print(f"resolution {f[1]:.2f} Hz, Grms (20 to 2000 Hz) = {grms:.1f} g")', 'Compare against the NASA 10 and 12.7 Grms levels', 2);
