INSERT INTO courses (slug, title, subtitle, description, discipline_id, level, instructor_name, instructor_role, updated, hue, position) VALUES ('imu-flight-data-acquisition', 'IMU and Flight Data Acquisition', 'Choose, read and trust inertial and vibration sensors, then design the computer that records them.', 'Learn what an IMU and a vibration channel must capture on a sounding rocket, how MEMS accelerometers and gyros really behave, how raw samples become attitude, velocity and flight events, and how to design the measurement computer that logs it all without losing the flight. The ranges and rates are traced to ASRI''s published Phoenix and SAFFIRE results and to NASA''s sounding-rocket handbook, so every number in the final specification has a source.', 'daq', 'Intermediate', 'DUT Space Science Centre', 'Launch and instrumentation team', '2026-11', 150, 2);
INSERT INTO course_also_disciplines (course_slug, discipline_id, position) VALUES ('imu-flight-data-acquisition', 'vibration-measurement', 0);
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'outcome', 0, 'Turn published flight and test data into sensor ranges, bandwidths and sample rates with stated margins');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'outcome', 1, 'Explain how MEMS accelerometers and gyros work, and read a datasheet for the specs that matter on a rocket');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'outcome', 2, 'Calibrate an IMU, and estimate attitude by integrating gyro rates with drift correction');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'outcome', 3, 'Predict how sensor bias and attitude error grow into velocity and position error, and detect launch, burnout and apogee');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'outcome', 4, 'Choose a vibration sensor and anti-alias filter, and compute PSD and Grms from logged data');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'outcome', 5, 'Specify a flight measurement computer: ADC chain, timing, logging, power and a safe arming scheme');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'prerequisite', 0, 'Electronics: op-amps, filters and how an ADC works');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'prerequisite', 1, 'Programming in C or Python, enough to read a sensor over SPI and process an array');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'prerequisite', 2, 'The sampling and vibration units of the Structures, Vibration and Dynamic Environments course help but are not required');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'audience', 0, 'Electronics and computer engineers joining the Centre''s launch and instrumentation work');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'audience', 1, 'Anyone preparing to build or review a flight data recorder for a hybrid or liquid sounding rocket');
INSERT INTO course_points (course_slug, kind, position, text) VALUES ('imu-flight-data-acquisition', 'audience', 2, 'Students collaborating with UKZN ASRI on flight and engine-test instrumentation');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('imu-flight-data-acquisition', 'm1', 'What the computer must measure', 'The real numbers from ASRI''s flights and tests, and how to turn them into ranges and rates.', 0);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'asri-flights', 'm1', 'What ASRI''s flights and tests produced', 30, 'Thrust, acceleration, roll rate and the data losses on ASRI''s Phoenix and SAFFIRE campaigns.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 0, 'h', '{"text":"Start from measured numbers, not guesses"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 1, 'p', '{"text":"A measurement computer is specified by the extremes it must record. ASRI at UKZN has published enough flight and test data to set those extremes for a hybrid sounding rocket and an 18 kN liquid engine. Everything below is from ASRI''s own papers and theses."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 2, 'h', '{"text":"Phoenix hybrid sounding rockets"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 3, 'table', '{"head":["Quantity","Phoenix-1C","Phoenix-1D"],"rows":[["Thrust (design)","4.44 kN","4.59 kN"],["Burn time (design)","12.1 s","14.9 s"],["Chamber pressure (design)","26.4 bar","27.2 bar"],["Peak axial acceleration (flown)","9.98 g (design limit 10 g)","not stated in the paper"],["Roll rate","3 Hz measured (1 080 °/s), 0.53 Hz predicted","2.66 Hz predicted (958 °/s); flat spin after apogee"],["Apogee","7.99 km (flight computer)","about 13 km, 23.7 km predicted"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 4, 'p', '{"text":"The flight computer on both vehicles is an Entacore AIM Xtra, flown in pairs on Phoenix-1C for redundancy. It reports acceleration, velocity, GPS position and angular rates by radio, and it detects apogee from inertial data plus GPS to fire a CO2 parachute ejector."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 5, 'h', '{"text":"SAFFIRE ABLE liquid engine"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 6, 'ul', '{"items":["About 18 kN thrust at 12 bar chamber pressure, LOX and Jet A-1 at roughly 5.7 and 2.3 kg/s.","Burns of 10 s, 16 s and 66 s tested, with the test facility designed for 100 s.","Instrumentation: thermocouples in the chamber wall, chamber pressure transducers, a load cell and a flow meter, controlled by a National Instruments CompactRIO running LabVIEW."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 7, 'callout', '{"kind":"key","title":"What the papers do not contain","text":"No ASRI paper reports a measured vibration spectrum, a Grms value or an accelerometer model. Vibration levels in this course come from NASA''s sounding-rocket handbook, not from ASRI, and should be replaced with ASRI''s data as soon as it exists."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 8, 'h', '{"text":"Where the data went wrong"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'asri-flights', 9, 'table', '{"head":["Event","What it teaches"],"rows":[["Phoenix-1C video lost: the battery drained while the rocket waited on the pad for clearance","Budget power for a long pad hold, or power the electronics from the umbilical"],["Phoenix-1D sensors began recording at different times after ignition","Log from power-up with one clock, and keep a pre-launch buffer"],["Phoenix-1C flight computer stopped recording before ocean impact","Telemeter a copy of the data so a lost recorder does not lose the flight"],["Phoenix-1D roll gyro stopped recording at the roll-rate peak","Check the gyro range and what the sensor does when it saturates"],["A hybrid motor chamber-pressure channel was sampled at about 10 samples per second by mistake, so the combustion instability could not be analysed","Choose and verify the sample rate before the test, not after"]]}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'asri-flights', 0, 'Phoenix peaks at about 10 g axial and 3 Hz (1 080 °/s) roll; ABLE runs at about 18 kN for up to 66 s.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'asri-flights', 1, 'ASRI has published no vibration measurements, so vibration levels need an outside reference.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'asri-flights', 2, 'Most of ASRI''s data problems were power, timing and sample-rate mistakes, not sensor limits.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 'asri-flights', 0, 'Preliminary Results from the 2023 Phoenix Hybrid Rocket Launch Campaign (AIAA 2024-1607)', 'AIAA', 'https://doi.org/10.2514/6.2024-1607', 'Gyasi-Agyei et al., flight results and avionics');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 'asri-flights', 1, 'Development of a Payload Module for the Phoenix-1C Hybrid Sounding Rocket (AIAA 2024-0372)', 'AIAA', 'https://doi.org/10.2514/6.2024-0372', 'Tshomela et al., the 9.98 g flight measurement');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 'm1', 'Turning flight numbers into sensor specs', 30, 'Range, margin, resolution, sample rate and data volume, worked from the ASRI figures.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 0, 'h', '{"text":"Range: peak times a margin"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 1, 'p', '{"text":"A sensor saturates when the input passes its full-scale range, and a saturated record is lost data. Pick the range from the largest plausible peak, then add margin for what you did not predict."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 2, 'eq', '{"text":"\\text{margin} = \\frac{\\text{full-scale range}}{\\text{expected peak}}","name":"Range margin"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 3, 'table', '{"head":["Channel","Expected peak","Candidate range","Margin"],"rows":[["Axial acceleration, Phoenix","9.98 g","±16 g","1.6"],["Axial acceleration, Phoenix","9.98 g","±32 g","3.2"],["Roll rate, Phoenix","1 080 °/s","±2 000 °/s","1.85"],["Roll rate, NASA-class (7 Hz)","2 520 °/s","±2 000 °/s","0.79 (saturates)"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 4, 'p', '{"text":"The Phoenix-1C roll rate was about six times what the simulation predicted. When a prediction can be that far off, margin of 1.5 to 2 is a minimum and 3 is comfortable."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 5, 'callout', '{"kind":"key","title":"Do not choose the range by the biggest number","text":"A wider range costs resolution and noise. A ±200 g accelerometer is wrong for a 10 g boost phase: its noise floor is much higher than a ±16 g part. Use the narrowest range with enough margin, and add a second sensor for rare high-g events such as shock."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 6, 'h', '{"text":"Bandwidth and sample rate"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 7, 'p', '{"text":"Sample rate $f_s$ must exceed twice the highest frequency of interest $f_{max}$ (the Nyquist limit), and practical designs use 2.5 to 5 times, because the anti-alias filter has a finite slope."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 8, 'eq', '{"text":"f_s \\ge 2.5\\,f_{max} \\quad\\text{to}\\quad 5\\,f_{max}","name":"Practical sample rate"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 9, 'ul', '{"items":["The IMU needs a bandwidth well above the vehicle''s rigid-body motion (a few Hz for roll, tens of Hz for manoeuvres): 1 kHz sampling is generous.","A vibration channel for NASA''s 20 to 2 000 Hz test band needs about 5 to 10 kS/s; if you also want shock or engine acoustics, 25 kS/s.","A 2 kHz test-stand DAQ sees only to 1 kHz: enough for chugging, not for screech."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 10, 'h', '{"text":"Data volume"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 11, 'eq', '{"text":"\\text{bytes} = N_{ch}\\;\\times\\;\\text{bytes per sample}\\;\\times\\; f_s\\;\\times\\; t","name":"Storage"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 12, 'p', '{"text":"Six IMU channels of 16 bits at 1 kHz for 15 minutes is 10.8 MB. Three vibration channels at 25 kS/s for 66 s is 9.9 MB. Storage is never the constraint; write speed and power are."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 0, 'Range margin is full scale divided by expected peak; aim for 2 or more, and do not use a wider range than needed.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 1, 'Sample at 2.5 to 5 times the highest frequency of interest, with a real anti-alias filter in front.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'ranges-rates', 2, 'Data volume is small; what fails is timing, power and write latency.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm1', 0, 'A gyro has a ±2 000 °/s range. A rocket''s roll peaks at 1 080 °/s. The margin is about:', '["0.54","1.85","3.0","5.4"]', 1, 'Margin is full scale over peak: 2 000 / 1 080 = 1.85.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm1', 1, 'Why not simply fit a ±200 g accelerometer for the whole flight?', '["It cannot measure 10 g","Its noise and resolution are worse at the low g levels that matter during boost","It is always digital","It needs no calibration"]', 1, 'A wider range spreads the same number of bits over more g, so resolution and noise are worse at the levels you actually fly.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm1', 2, 'A 10 kS/s channel is intended to reach 2 kHz. The ratio fs to f_max is:', '["2","5","20","0.2"]', 1, '10 000 / 2 000 = 5, comfortably within 2.5 to 5.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm1', 3, 'What did ASRI''s roll-rate result show about prediction?', '["Prediction was accurate","Measured roll was about six times predicted","Roll was zero","Roll could not be measured"]', 1, '3 Hz was measured against 0.53 Hz predicted, so large margins are needed.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('imu-flight-data-acquisition', 'm2', 'Inertial sensors', 'How MEMS accelerometers and gyros work, what their errors are, and how to calibrate them.', 1);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'mems-accel', 'm2', 'How a MEMS accelerometer works', 30, 'A proof mass on springs, capacitive sensing, and the specs that matter: range, noise density, bandwidth and bias.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 0, 'h', '{"text":"A mass on a spring, etched in silicon"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 1, 'p', '{"text":"A MEMS accelerometer is a tiny proof mass held by silicon springs. When the package accelerates, the mass lags and moves relative to the frame. Interdigitated plates form capacitors whose values change with the displacement, and an on-chip circuit converts that to a voltage or a digital word."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 2, 'eq', '{"text":"m\\ddot{x} + c\\dot{x} + kx = -m\\,a_{frame}","name":"Proof-mass equation"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 3, 'p', '{"text":"This is the SDOF oscillator from the vibration course. Below its natural frequency the displacement is proportional to acceleration; the mechanical resonance, and the damping chosen to control it, limit the usable bandwidth."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 4, 'h', '{"text":"The specs that matter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 5, 'table', '{"head":["Spec","Meaning","Why it matters on a rocket"],"rows":[["Full-scale range","Largest acceleration it can report","Saturation loses the record"],["Noise density (µg/√Hz)","Random noise per root hertz","Sets resolution at the bandwidth you use"],["Bandwidth or output data rate","Highest frequency passed","Sets what vibration you can see"],["Bias and bias drift","Output with zero input, and how it changes with temperature","Integrates into velocity and position error"],["Scale factor error","Gain error","Under- or over-reads peaks"],["Shock survival","Largest shock without damage (often 10 000 g)","Separation and pyro events"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 6, 'eq', '{"text":"\\sigma_{rms} = N_a\\,\\sqrt{BW}","name":"Noise from density and bandwidth"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 7, 'p', '{"text":"A 70 µg/√Hz part read over a 500 Hz bandwidth has $\\sigma = 70\\times10^{-6}\\sqrt{500} = 1.57$ mg rms. That is negligible against a 10 g boost, but it matters when you integrate."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-accel', 8, 'callout', '{"kind":"warn","title":"Digital parts hide a filter","text":"A digital accelerometer has an internal filter and output rate. Read the datasheet to find out whether it aliases above its output rate. A ±200 g digital part such as the ADXL375 has a 3.2 kHz maximum output rate and a bandwidth near 1.6 kHz (check the current datasheet), so it cannot also be a 10 kHz vibration channel."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'mems-accel', 0, 'A MEMS accelerometer is a damped mass-spring; its resonance limits bandwidth.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'mems-accel', 1, 'Noise is $N_a\sqrt{BW}$: choose bandwidth deliberately.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'mems-accel', 2, 'Wide-range digital parts have limited bandwidth and coarser resolution; check the datasheet.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 'm2', 'How a MEMS gyroscope works', 30, 'A vibrating structure and the Coriolis effect, and the gyro specs that matter on a spinning rocket.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 0, 'h', '{"text":"Rotation is sensed through Coriolis force"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 1, 'p', '{"text":"A MEMS gyro drives a proof mass to vibrate along one axis. When the package rotates, the Coriolis effect pushes the mass sideways, perpendicular to both the vibration and the rotation axis. The sideways motion, sensed capacitively, is proportional to the angular rate."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 2, 'eq', '{"text":"\\vec{a}_{Coriolis} = -2\\,\\vec{\\Omega}\\times\\vec{v}","name":"Coriolis acceleration"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 3, 'h', '{"text":"What to read on a gyro datasheet"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 4, 'table', '{"head":["Spec","Meaning","Rocket relevance"],"rows":[["Full-scale range (°/s)","Largest rate reported","Roll can reach 1 000 to 2 500 °/s"],["Rate noise density (°/s/√Hz)","Random noise","Angle noise grows as the square root of time"],["Bias instability","Slow wander of the zero-rate output","Integrates to angle drift"],["Temperature coefficient","Bias and scale change with temperature","A rocket sits in the sun, then flies"],["g-sensitivity","Output error caused by acceleration","Boost is 10 g or more"],["Vibration sensitivity","Error produced by vibration near the sensor''s drive frequency","Motor vibration is broadband"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 5, 'p', '{"text":"A gyro with 2.8 m°/s/√Hz noise density accumulates an angle noise of $2.8\\times10^{-3}\\sqrt{15} = 0.011°$ over a 15 s burn. Random noise is rarely the problem. Bias is."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 6, 'eq', '{"text":"\\theta_{err} = b\\,t","name":"Angle error from a constant bias"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 7, 'p', '{"text":"A bias of only 0.1 °/s becomes a 6° attitude error after 60 s. Estimate the bias at rest before launch and subtract it."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 8, 'callout', '{"kind":"warn","title":"Saturation is not graceful","text":"When the rate exceeds the range, some gyros clip and some wrap or drop out. ASRI''s Phoenix-1D roll gyro stopped recording at the roll-rate peak; the paper does not say why, but a range or saturation limit is a candidate. Know what your gyro does beyond its range."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 0, 'A MEMS gyro senses rate through the Coriolis force on a vibrating mass.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 1, 'Bias error grows linearly in angle: $\theta = bt$. Estimate and remove it before launch.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'mems-gyro', 2, 'Check range, g-sensitivity and saturation behaviour for a spinning, accelerating vehicle.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'imu-errors', 'm2', 'IMU error model and calibration', 35, 'Bias, scale factor and misalignment, a six-position gravity calibration, and a stationary gyro bias test.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 0, 'h', '{"text":"Every IMU channel is wrong in the same few ways"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 1, 'eq', '{"text":"\\hat a = (1 + s)\\,a + b + n","name":"One-axis error model","caption":"Measured value equals scale-factor error times truth, plus bias and noise"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 2, 'ul', '{"items":["**Bias** $b$: output with no input. Changes with temperature and between power-ups.","**Scale factor** $s$: gain error, often 0.1 to 1 percent.","**Misalignment and cross-axis:** the three sensor axes are not exactly orthogonal, and the board is not exactly aligned with the rocket.","**Noise** $n$: random, set by noise density and bandwidth."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 3, 'h', '{"text":"Six-position accelerometer calibration"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 4, 'p', '{"text":"Gravity is a free reference. Hold the IMU still with each axis pointing up, then down, and record the average. For one axis, with readings $a_+$ (axis up, true +1 g) and $a_-$ (axis down, true −1 g):"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 5, 'eq', '{"text":"b = \\frac{a_+ + a_-}{2}, \\qquad s = \\frac{a_+ - a_-}{2\\,g} - 1","name":"Bias and scale factor from two positions"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 6, 'p', '{"text":"If the readings are +1.02 g and −0.98 g, the bias is 0.02 g and the scale factor is 0, exactly. If they are +1.05 g and −1.05 g, the bias is zero and the scale is 5 percent high."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 7, 'h', '{"text":"Gyro bias at rest"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 8, 'p', '{"text":"Leave the IMU stationary for a few minutes. The mean of each gyro axis is its bias, and the standard deviation is the noise at that bandwidth. Repeat at different temperatures, and again after power-up on the pad, because bias changes at each start."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 9, 'callout', '{"kind":"tip","title":"Do the calibration at the pad","text":"A gyro bias measured on the bench and applied unchanged in flight is wrong by whatever the temperature and the new power-up changed. Log 30 s of stationary data at the pad, before arming, and use it to correct the gyros."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'imu-errors', 10, 'callout', '{"kind":"key","title":"Allan variance","text":"To separate noise from slow drift, log several hours stationary and plot the Allan deviation against averaging time. The V-shaped curve shows white noise on the falling side and bias instability at the minimum. It tells you how long you can average before drift wins."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'imu-errors', 0, 'Each channel is $\hat a = (1+s)a + b + n$: scale factor, bias and noise.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'imu-errors', 1, 'Six-position gravity calibration gives accelerometer bias and scale factor.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'imu-errors', 2, 'Measure gyro bias at the pad just before flight, not only on the bench.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm2', 0, 'A MEMS accelerometer''s usable bandwidth is limited mainly by:', '["Its supply voltage","Its mechanical resonance and internal filter","The cable length","Its package colour"]', 1, 'The proof mass is a damped oscillator; above its resonance it no longer follows the input.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm2', 1, 'A gyro has a 0.1 °/s uncorrected bias. After 60 s the angle error is:', '["0.1°","0.6°","6°","60°"]', 2, '$\theta = bt = 0.1 \times 60 = 6°$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm2', 2, 'Six-position readings are +1.02 g and −0.98 g. The accelerometer bias is:', '["0","0.02 g","0.04 g","1.00 g"]', 1, 'Bias is the mean of the two readings: (1.02 − 0.98)/2 = 0.02 g.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm2', 3, 'Why measure gyro bias at the pad?', '["Bias is zero on the pad","Bias changes with temperature and each power-up","Gyros need no calibration","It saves battery"]', 1, 'A bench value goes stale after the temperature and power cycle change, so the last measurement before launch is the best.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('imu-flight-data-acquisition', 'm3', 'From raw samples to attitude and events', 'Frames, rotations, attitude estimation, error growth, and detecting launch, burnout and apogee.', 2);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 'm3', 'Frames, rotations and quaternions', 30, 'Body and launch frames, why Euler angles fail near vertical, and how quaternions avoid it.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 0, 'h', '{"text":"Two frames"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 1, 'ul', '{"items":["The **body frame** is fixed to the rocket: x along the axis, y and z across. The IMU reports in this frame.","The **launch frame** is fixed to the ground: up, east, north. Position, velocity and gravity are naturally written here."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 2, 'p', '{"text":"Attitude is the rotation from one to the other. Three Euler angles (roll, pitch, yaw) are the intuitive way to describe it, and they have a flaw."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 3, 'h', '{"text":"Gimbal lock on a near-vertical rocket"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 4, 'p', '{"text":"When the pitch angle reaches 90°, roll and yaw describe the same rotation and the Euler-angle equations divide by zero. ASRI launched Phoenix at 75° and 85° elevation, which is close enough to vertical for Euler-angle roll and yaw to become unreliable."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 5, 'h', '{"text":"Quaternions"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 6, 'p', '{"text":"A quaternion has four numbers that describe an orientation without any singularity. Integrating the gyro rates into a quaternion is simple."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 7, 'eq', '{"text":"\\dot{q} = \\tfrac12\\, q \\otimes (0, \\omega_x, \\omega_y, \\omega_z)","name":"Quaternion kinematics"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 8, 'eq', '{"text":"q_{k+1} = q_k + \\tfrac12\\, q_k \\otimes (0,\\vec\\omega)\\,\\Delta t \\quad\\text{then normalise}","name":"A simple update step"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 9, 'p', '{"text":"At 1 kHz and 1 080 °/s, each step rotates 1.08°. The simple update is accurate enough at that step; at a lower rate you must use the exact rotation per step."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 10, 'callout', '{"kind":"key","title":"Store quaternions, show Euler angles","text":"Run the filter and the log in quaternions. Convert to roll, pitch and yaw only when plotting, and mark any record where pitch is near 90° as unreliable."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 0, 'The IMU measures in the body frame; gravity and position live in the launch frame.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 1, 'Euler angles lose a degree of freedom near 90° pitch, which a near-vertical rocket reaches.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'frames-rotations', 2, 'Quaternions integrate gyro rates without a singularity; renormalise after every step.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'attitude', 'm3', 'Integrating gyros and correcting drift', 35, 'Why gyro integration drifts, why an accelerometer cannot give tilt during boost, and how a complementary filter or a Kalman filter combine them.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 0, 'h', '{"text":"Gyro integration: smooth but drifting"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 1, 'p', '{"text":"Integrating the angular rate gives attitude that is smooth and responsive and that wanders away from the truth as the bias accumulates. On a stationary device the accelerometer can correct that drift: it measures gravity, which points down."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 2, 'h', '{"text":"The accelerometer measures specific force, not gravity"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 3, 'p', '{"text":"An accelerometer reports the non-gravitational acceleration, called the specific force. At rest it reads +1 g upward. In free fall it reads zero. During a motor burn it reads the thrust acceleration, which points along the body axis, not down."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 4, 'callout', '{"kind":"key","title":"Tilt correction fails when the rocket is accelerating","text":"During boost the accelerometer points along the rocket''s axis no matter how the rocket is tilted. It carries no tilt information, so a tilt correction that trusts it will drive the estimate toward the thrust direction. Correct tilt only when the specific-force magnitude is close to 1 g, and let the gyro run alone during boost."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 5, 'h', '{"text":"The complementary filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 6, 'eq', '{"text":"\\theta_{k+1} = \\alpha\\,(\\theta_k + \\omega\\,\\Delta t) + (1-\\alpha)\\,\\theta_{acc}","name":"Complementary filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 7, 'p', '{"text":"The gyro term dominates over short times and the accelerometer term over long times. The crossover time constant is $\\tau = \\alpha\\,\\Delta t/(1-\\alpha)$; with $\\alpha = 0.98$ and $\\Delta t = 10$ ms, $\\tau = 0.49$ s."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 8, 'h', '{"text":"Kalman filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 9, 'p', '{"text":"A Kalman filter extends this idea: it carries an estimate and its uncertainty, predicts with the gyro, and corrects with whatever else is available, such as GPS, barometer or the accelerometer when it can be trusted, each weighted by its uncertainty. It can also estimate the gyro bias as part of the state."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'attitude', 10, 'callout', '{"kind":"tip","title":"Log raw data, filter offline","text":"Run a simple filter on the vehicle for event detection, but always log the raw gyro and accelerometer samples. You can run a better filter on the ground and improve the answer after the flight."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'attitude', 0, 'Gyro integration drifts; the accelerometer corrects tilt only when it measures gravity.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'attitude', 1, 'During boost the accelerometer measures thrust, so tilt correction must be switched off.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'attitude', 2, 'A complementary filter blends the two with time constant $\tau = \alpha\Delta t/(1-\alpha)$; a Kalman filter weights each by its uncertainty.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 'attitude', 0, 'Kalman and Bayesian Filters in Python (Labbe)', 'Open textbook', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'A free, code-first introduction to Kalman filters');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 'm3', 'Velocity, altitude and flight events', 35, 'How small errors grow into large position errors, and how to detect launch, burnout and apogee.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 0, 'h', '{"text":"Double integration is unforgiving"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 1, 'p', '{"text":"Velocity is the integral of acceleration and position is the integral of velocity, so errors grow fast."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 2, 'eq', '{"text":"\\delta v = b\\,t, \\qquad \\delta x = \\tfrac12\\,b\\,t^2","name":"Error from a constant acceleration bias"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 3, 'p', '{"text":"A bias of 0.05 m/s² (about 5 mg) gives $\\delta v = 2$ m/s and $\\delta x = 40$ m after 40 s."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 4, 'h', '{"text":"Attitude error leaks gravity"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 5, 'p', '{"text":"To get motion from the accelerometer you must subtract gravity, and to do that you must know which way it points. A small attitude error $\\delta\\theta$ leaks a fraction of gravity into the measured acceleration."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 6, 'eq', '{"text":"a_{leak} = g\\sin\\delta\\theta","name":"Gravity leakage"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 7, 'p', '{"text":"A 1° attitude error leaks $9.81\\sin 1° = 0.171$ m/s², which is 3.4 times the 5 mg bias above. After 40 s that is 6.8 m/s and 137 m. Attitude is the largest error source in a free inertial solution."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 8, 'callout', '{"kind":"key","title":"Aid the inertial solution","text":"ASRI''s flight computer combines inertial data with GPS. A barometer, GPS and radar tracking each bound the drift in a different way: use at least one aid, and compare against the range''s radar track after the flight."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 9, 'h', '{"text":"Detecting events"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 10, 'table', '{"head":["Event","Typical detector","How it fails"],"rows":[["Launch","Axial acceleration above 2 g for 100 ms","Handling bumps or a short vibration spike trigger it; the delay hides the first moments unless you keep a pre-trigger buffer"],["Burnout","Axial acceleration falls sharply to near zero or negative (drag only)","A motor that surges or chuffs can look like burnout"],["Apogee","Vertical velocity crosses zero, or barometric altitude peaks, or pressure turns","Pressure sensing is unreliable near Mach 1; GPS can drop out at high acceleration"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 11, 'callout', '{"kind":"warn","title":"Recovery is a safety function","text":"A false apogee deploys a parachute at 400 m/s. ASRI''s Phoenix-1C paper notes the parachute''s design dynamic-pressure limit would have been exceeded had it deployed at the apogee actually flown. Use two independent detectors for any recovery trigger, and do not let the measurement computer fire pyrotechnics without a separate hardware safety."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 0, 'A constant bias gives $\delta x = \tfrac12 bt^2$; a 5 mg bias is 40 m in 40 s.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 1, 'An attitude error $\delta\theta$ leaks $g\sin\delta\theta$: 1° is 6.8 m/s and 137 m in 40 s.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'trajectory-events', 2, 'Event detectors need a pre-trigger buffer and a second independent source for recovery.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm3', 0, 'A rocket launched at 85° elevation is a problem for Euler-angle attitude because:', '["Roll is zero","Pitch near 90° makes roll and yaw ambiguous (gimbal lock)","Gyros cannot measure pitch","It has no yaw"]', 1, 'At 90° pitch the roll and yaw axes align; the equations are singular.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm3', 1, 'During motor burn, an accelerometer mainly reports:', '["Gravity direction","Thrust acceleration along the body axis","Zero","The magnetic field"]', 1, 'It measures specific force, which during boost is thrust along the axis, so it carries no tilt information.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm3', 2, 'A 0.05 m/s² bias after 40 s gives a position error of:', '["2 m","20 m","40 m","80 m"]', 2, '$\delta x = \tfrac12 b t^2 = 0.5 \times 0.05 \times 1600 = 40$ m.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm3', 3, 'Which is the safest way to trigger a parachute at apogee?', '["One barometer reading","Two independent detectors, with a separate hardware safety","A timer set on the bench","Manual command only"]', 1, 'A false trigger at high speed can destroy the vehicle, so recovery needs redundancy and a hardware safety.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('imu-flight-data-acquisition', 'm4', 'Vibration measurement for a rocket', 'Choosing a vibration sensor, the levels to expect, and the anti-alias filter that protects the data.', 3);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 'm4', 'Vibration sensors: piezoelectric versus MEMS', 30, 'IEPE and charge-mode piezoelectric accelerometers, high-bandwidth MEMS parts, and how to mount them.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 0, 'h', '{"text":"Two families"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 1, 'table', '{"head":["Type","Strengths","Limits"],"rows":[["Piezoelectric, IEPE (a built-in amplifier on a constant-current line)","Wide bandwidth to tens of kHz, low noise, standard in vibration labs","Needs a constant-current source and AC coupling; no response to steady acceleration; costly"],["Piezoelectric, charge mode","Survives very high temperatures","Needs a charge amplifier and low-noise cable"],["MEMS, analog (±100 g class)","Small, cheap, responds to steady acceleration, bandwidth to tens of kHz in some parts","Higher noise than a laboratory piezo, single axis in some parts"],["MEMS, digital (±200 g class)","Three axes, simple to read over SPI","Output rate and bandwidth in the low kHz"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 2, 'p', '{"text":"For a flight recorder that must see to 2 kHz at up to 100 g, an analog MEMS accelerometer or an IEPE piezo is the usual choice. A digital part that is limited to 1.6 kHz cannot do the job."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 3, 'h', '{"text":"Mounting decides what you measure"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 4, 'ul', '{"items":["The mounting resonance, from the sensor''s mass and the stiffness of its attachment, is a spring-mass system on top of your structure. A soft mount puts a resonance in the band.","Stud mounting is stiffest; adhesive is next; a magnet or tape is worst above about 2 kHz.","Mount on a stiff part of the structure close to the item of interest, and note the direction of each axis."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 5, 'callout', '{"kind":"tip","title":"See the structures course","text":"The Structures, Vibration and Dynamic Environments course has a lesson on installation and mounting and a lab on mounting resonance. Use them to choose and check the mount."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 6, 'callout', '{"kind":"warn","title":"Vibration also disturbs the IMU","text":"A gyro or accelerometer exposed to vibration can produce a false offset. A mount that isolates the IMU from high-frequency vibration, with the vibration sensor on the rigid structure, keeps the two jobs separate."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 0, 'Pick the vibration sensor by bandwidth and range: IEPE piezo or analog MEMS, not a bandwidth-limited digital part.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 1, 'The mount sets the useful bandwidth; stud mounting is stiffest.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 2, 'Isolate the IMU from vibration and keep a separate vibration sensor on rigid structure.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 'vib-sensors', 0, 'Guide to Accelerometer Installation (TP319)', 'Endevco', NULL, 'Study library #23');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'vib-levels', 'm4', 'Vibration levels to expect and how to compare', 30, 'NASA''s sounding-rocket test levels, Grms from a PSD, and the statistics of a short record.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 0, 'h', '{"text":"A published reference"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 1, 'p', '{"text":"ASRI has not published vibration data, so the levels here come from NASA''s Sounding Rockets Program Handbook (810-HB-SRP), Table 6.3.4-1. These are flight-acceptance test levels for payloads, not measured flight data, and they define what your electronics should survive."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 2, 'table', '{"head":["Vehicle class","Thrust axis","Lateral axes","Duration"],"rows":[["Level 1 (single-stage Improved Orion and similar)","10.0 Grms, 0.051 g²/Hz, 20 to 2 000 Hz","7.6 Grms, 0.029 g²/Hz, 20 to 2 000 Hz","20 s per axis"],["Level 2 (Black Brant family)","12.7 Grms, 0.01 g²/Hz at 20 Hz rising 1.8 dB per octave to 0.10 g²/Hz at 1 kHz, flat to 2 kHz","same in all axes","10 s per axis"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 3, 'h', '{"text":"From a PSD to Grms"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 4, 'eq', '{"text":"G_{rms} = \\sqrt{\\int_{f_1}^{f_2} \\mathrm{PSD}(f)\\,df}","name":"Root-mean-square acceleration"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 5, 'p', '{"text":"For a flat PSD of 0.051 g²/Hz from 20 to 2 000 Hz, $G_{rms} = \\sqrt{0.051\\times 1980} = 10.05$. The peak of a Gaussian random signal reaches about 3 times the rms, so about 30 g at Level 1 and 38 g at Level 2. That is why a ±100 g sensor range has comfortable margin, and ±200 g is not needed."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 6, 'h', '{"text":"Computing a PSD from your log"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 7, 'ul', '{"items":["Split the record into segments, window each, take an FFT, and average: this is **Welch''s method**.","Frequency resolution is $\\Delta f = f_s/N_{fft}$. At 10 kS/s and 4096 points, $\\Delta f = 2.44$ Hz.","Averaging $N_{avg}$ segments gives a random error of about $1/\\sqrt{N_{avg}}$: 50 averages is 14 percent."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'vib-levels', 8, 'callout', '{"kind":"key","title":"A short record limits precision","text":"A 12 s burn at 10 kS/s gives 120 000 samples, which is about 29 non-overlapping 4096-point segments and about 19 percent random error. Plan record lengths and nfft together, and report the resolution and number of averages with every PSD."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'vib-levels', 0, 'NASA gives 10 Grms (Level 1) and 12.7 Grms (Level 2) as flight-acceptance random levels from 20 to 2 000 Hz.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'vib-levels', 1, 'Grms is the square root of the area under the PSD; peaks reach about 3 times Grms.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'vib-levels', 2, 'PSD resolution is $f_s/N_{fft}$, and random error falls as $1/\sqrt{N_{avg}}$.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 'vib-levels', 0, 'Sounding Rockets Program Handbook (810-HB-SRP), section 6.3.4', 'NASA Wallops', 'https://www.nasa.gov/wp-content/uploads/2023/09/sounding-rocket-program-handbook.pdf', 'Table 6.3.4-1 vibration test levels');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'anti-alias', 'm4', 'Anti-alias filters and the sampling choice', 35, 'How many poles you need to protect a 2 kHz band when sampling at 10 kS/s.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 0, 'h', '{"text":"Aliasing cannot be fixed afterwards"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 1, 'p', '{"text":"A frequency above half the sample rate folds back into the band and looks like a real, lower frequency. Once sampled, an aliased component cannot be told from a genuine one. The only cure is to remove it before the ADC with an analog filter."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 2, 'h', '{"text":"Sizing a Butterworth filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 3, 'p', '{"text":"A Butterworth low-pass filter of order $n$ and cutoff $f_c$ passes a signal at frequency $f$ with magnitude $1/\\sqrt{1+(f/f_c)^{2n}}$."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 4, 'eq', '{"text":"A_{dB}(f) = 10\\log_{10}\\!\\left[1 + \\left(\\frac{f}{f_c}\\right)^{2n}\\right]","name":"Attenuation of a Butterworth filter"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 5, 'p', '{"text":"The troublesome frequency is the one that folds into the top of your band: $f_s - f_{max}$. With $f_s = 10$ kHz and a 2 kHz band, a component at 8 kHz folds to 2 kHz."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 6, 'table', '{"head":["Poles","Attenuation at 8 kHz with $f_c = 2$ kHz"],"rows":[["4","48 dB"],["5","60 dB"],["6","72 dB"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 7, 'p', '{"text":"To push an alias below one 16-bit step (about 96 dB) you would need about 8 poles, which is heavy and loses phase accuracy. Two cheaper routes exist."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 8, 'ul', '{"items":["**Oversample:** sample at 25 kS/s and filter digitally to 2 kHz. The alias frequency moves to 23 kHz and a low-order analog filter is enough.","**Sigma-delta ADC:** these oversample internally and filter digitally; only a simple analog filter is needed in front."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 9, 'callout', '{"kind":"warn","title":"Digital sensors alias too","text":"A digital accelerometer that samples internally at a high rate and then reports at a lower output rate may alias unless it has an internal filter. Read the datasheet''s filter section and check with a swept-sine test."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'anti-alias', 10, 'callout', '{"kind":"tip","title":"Test it","text":"Put a function generator on the input and sweep to 3 or 4 times the Nyquist frequency. Any output that tracks the generator downward is an alias."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'anti-alias', 0, 'Aliasing must be prevented with an analog filter before the ADC.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'anti-alias', 1, 'Butterworth attenuation is $10\log_{10}[1 + (f/f_c)^{2n}]$; five poles give 60 dB at four times the cutoff.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'anti-alias', 2, 'Oversampling and a sigma-delta ADC cut the filter order needed.');
INSERT INTO lesson_refs (course_slug, lesson_id, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 'anti-alias', 0, 'Anti-aliasing filter design for a 100 kHz DAQ signal chain (SBAA655)', 'Texas Instruments', NULL, 'Study library #20');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm4', 0, 'Which sensor cannot serve as a 10 kHz vibration channel?', '["An IEPE piezo accelerometer","A digital ±200 g part with a 1.6 kHz bandwidth","An analog MEMS part with a 20 kHz bandwidth","A charge-mode piezo"]', 1, 'A 1.6 kHz bandwidth cannot see 10 kHz.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm4', 1, 'A flat PSD of 0.029 g²/Hz from 20 to 2 000 Hz has an rms of about:', '["1.9 Grms","3.8 Grms","7.6 Grms","15 Grms"]', 2, '$\sqrt{0.029\times1980} = 7.58$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm4', 2, 'With 50 averages, the random error of a PSD estimate is about:', '["1.4 percent","14 percent","50 percent","2 percent"]', 1, '$1/\sqrt{50} = 0.14$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm4', 3, 'Why can aliasing not be fixed in software?', '["The CPU is too slow","Aliased components look identical to real low-frequency signal once sampled","ADCs do not alias","Software filters are illegal"]', 1, 'After sampling, an aliased tone and a genuine tone at the same frequency are the same numbers.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('imu-flight-data-acquisition', 'm5', 'The measurement computer', 'The architecture, the timing and logging discipline, and the power and safety rules.', 4);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'architecture', 'm5', 'Architecture: sensors, ADC, MCU, storage and radio', 35, 'What the blocks are, how the IMU is read, and how much bus capacity you really need.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 0, 'h', '{"text":"The blocks"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 1, 'ol', '{"items":["**IMU** (accelerometer and gyro) on SPI, read at a fixed rate with a data-ready interrupt.","**Vibration channel:** an analog accelerometer, anti-alias filter and an ADC, sampled by hardware timer and DMA so the CPU does not miss a sample.","**GPS and barometer** for aiding and apogee detection.","**MCU** with enough RAM for ring buffers and a floating-point unit if you filter on board.","**Storage:** an SD card or flash with a write buffer, and optionally FRAM for critical state.","**Radio** to send a decimated copy to the ground.","**Power** with a regulator, battery monitor and an arming switch."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 2, 'h', '{"text":"Reading the IMU"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 3, 'p', '{"text":"SPI is the usual interface. Six 16-bit channels is 12 bytes, and with one address byte, 13 bytes per sample. At 1 kHz that is 104 kbit/s, so an 8 MHz SPI clock is 1.3 percent utilised."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 4, 'eq', '{"text":"\\text{utilisation} = \\frac{8\\,N_{bytes}\\,f_s}{f_{SPI}}","name":"SPI bus load"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 5, 'ul', '{"items":["Use the sensor''s **data-ready** line to trigger the read in an interrupt, and timestamp it in hardware, not in the main loop.","Use DMA for the ADC and SPI transfers so the cost per sample is a few microseconds.","Keep interrupt service routines short; write data into a ring buffer and let the main loop handle the slow work."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 6, 'h', '{"text":"The ADC"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 7, 'p', '{"text":"Choose the resolution from the dynamic range you need. 16 bits gives about 96 dB of range; a 12-bit converter gives 72 dB. ASRI found a 12-bit ADC too coarse for one small-signal measurement. Choose the sample rate from the filter design, and run the ADC from a timer so the sample spacing is exactly constant."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'architecture', 8, 'callout', '{"kind":"key","title":"Hardware timing, not software timing","text":"If a loop that reads a sensor is paced by the CPU, the sample spacing jitters whenever the CPU is busy writing to the card. A hardware timer triggering the ADC, or a sensor''s own clock, keeps the spacing fixed."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'architecture', 0, 'A measurement computer is a sensor-to-buffer pipeline: IMU, ADC, MCU, storage, radio.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'architecture', 1, 'Read sensors by interrupt and DMA with hardware timestamps; the bus load is small.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'architecture', 2, 'Pick the ADC resolution from the dynamic range and keep sampling timer-driven.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'timing-logging', 'm5', 'Time, logging and surviving a bad flight', 30, 'One clock, a pre-launch buffer, write-latency buffering, and logging that survives power loss.', 1);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 0, 'h', '{"text":"One clock for everything"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 1, 'p', '{"text":"ASRI''s Phoenix-1D flight computer sensors began recording at different times after ignition, and the start time of the acceleration record is uncertain in the paper. Give every channel a timestamp from one counter, and record a GPS time reference when available."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 2, 'ul', '{"items":["Stamp each sample at its data-ready interrupt from a free-running hardware counter.","Record the GPS pulse-per-second edge against the counter so you can convert to UTC afterwards.","Write a marker into the log at the moment of launch detection, and record the detection threshold, so the range''s radar record can be aligned."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 3, 'h', '{"text":"Record before the launch is detected"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 4, 'p', '{"text":"A launch detector triggers after a delay. If you start recording only then, you lose the start. Instead, record continuously into a circular buffer and keep a few seconds before the trigger."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 5, 'ul', '{"items":["Five seconds of 6-channel IMU data at 1 kHz is 60 kB, which fits in microcontroller RAM.","Two seconds of 3-channel vibration data at 25 kS/s is 300 kB, which needs external RAM or a lower rate before trigger."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 6, 'h', '{"text":"Storage is slower than it looks"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 7, 'p', '{"text":"An SD card averages a high write speed, but a block write occasionally stalls for 100 ms or more while the card housekeeps. Your buffer must hold the data that arrive during the stall. At 150 kB/s and a 200 ms stall, that is 30 kB."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 8, 'eq', '{"text":"\\text{buffer} \\ge \\text{data rate}\\times\\text{worst-case stall}","name":"Minimum write buffer"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 9, 'h', '{"text":"Log so that damage is survivable"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 10, 'ul', '{"items":["Write fixed-size binary blocks, each with a sequence number and a checksum, so a corrupted block can be skipped and lost data counted.","Flush the buffer to the card every fraction of a second, not at the end of the flight.","Write a short header with the firmware version, sensor ranges, sample rates and calibration values, so the log explains itself.","Send a decimated stream by radio, so a recorder lost at impact leaves something behind. ASRI''s Phoenix-1C recorder stopped before the ocean impact."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'timing-logging', 11, 'callout', '{"kind":"warn","title":"Test the unhappy paths","text":"Power the computer down in the middle of a write and confirm the log is still readable. Pull the card, fill the card, and drop the battery voltage. A bench demo that only works when nothing goes wrong has not been tested."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'timing-logging', 0, 'Timestamp every channel from one hardware counter and keep a GPS time reference.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'timing-logging', 1, 'Record into a circular buffer so the start of the launch is not lost.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'timing-logging', 2, 'Size the write buffer as data rate times the worst-case card stall; log in checksummed blocks and send a decimated stream by radio.');
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'power-safety', 'm5', 'Power, arming and fail-safe design', 30, 'Battery sizing for a long pad hold, hardware arming, and the line between measurement and control.', 2);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 0, 'h', '{"text":"Power for the whole wait, not the flight"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 1, 'p', '{"text":"A rocket may sit on the pad for hours, as ASRI''s Phoenix-1C did while waiting for weather clearance. The video system''s battery drained before launch. Size the battery for the pad hold plus the flight plus margin."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 2, 'eq', '{"text":"C = I\\,t_{hold}\\times\\text{margin}","name":"Battery capacity"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 3, 'p', '{"text":"A 150 mA computer on a 6 hour hold needs 900 mAh, and with a 1.5 times margin, 1 350 mAh. Options if that is too heavy: sleep until armed, power the electronics from the umbilical on the pad, and add a battery-voltage log and a low-battery telemetry flag."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 4, 'h', '{"text":"Arming"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 5, 'ul', '{"items":["A **hardware arm switch**, accessible from outside the vehicle, enables anything that matters. Software cannot arm itself.","Default state on power-up is safe: outputs off, no firing.","A **brown-out** detector holds the processor in reset until the supply is stable, and the watchdog restarts a hung program."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 6, 'h', '{"text":"Measurement is not control"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 7, 'callout', '{"kind":"key","title":"Keep the data computer read-only","text":"The ASRI facility runs engine control through a National Instruments CompactRIO. A DAQ computer should read sensor lines and never switch valves, igniters or pyrotechnics. Leave propellant handling, LOX work and ignition to ASRI''s fluid-systems engineers, and add the DAQ to the stand without changing the safety system."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 8, 'callout', '{"kind":"warn","title":"Radio and range rules","text":"A telemetry transmitter needs a legal frequency and power for the place you launch from. ASRI''s flight computer uses the 432 to 434 MHz band at 50 mW; confirm your own licence and range requirements with the range and the regulator before you transmit."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'power-safety', 9, 'callout', '{"kind":"tip","title":"Interlock the bench too","text":"Power cycling, connector pulling and shorted pins should leave the computer safe. Write down every fault you tested and what happened."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'power-safety', 0, 'Size the battery as $C = I\,t_{hold}\times$ margin; 150 mA for 6 hours with 1.5 margin is 1 350 mAh.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'power-safety', 1, 'Arm with a hardware switch and default to safe on power-up.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'power-safety', 2, 'A measurement computer reads sensors; it never controls valves, igniters or pyrotechnics.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm5', 0, 'An IMU sends 13 bytes per sample at 1 kHz over an 8 MHz SPI. The bus is about:', '["1.3 percent busy","13 percent busy","50 percent busy","Overloaded"]', 0, '$13\times8\times1000/8\times10^6 = 0.013$.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm5', 1, 'Why use a circular pre-trigger buffer?', '["To save power","To keep the data from before the launch detector fired","To slow the sample rate","To lower the noise"]', 1, 'Detection lags the event, so a continuous buffer lets you keep the moments before it.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm5', 2, 'An SD card stalls for 200 ms while data arrive at 150 kB/s. The buffer must hold at least:', '["3 kB","30 kB","300 kB","3 MB"]', 1, '150 000 B/s × 0.2 s = 30 000 B.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm5', 3, 'Which is the right role for the flight data computer?', '["Fire the igniter","Read sensors and log data without controlling valves or igniters","Fill the propellant tanks","Open the vent valve"]', 1, 'The measurement computer is read-only; control stays with ASRI''s own safety-rated systems.');
INSERT INTO modules (course_slug, id, title, summary, position) VALUES ('imu-flight-data-acquisition', 'm6', 'Capstone: specify the computer', 'Trace every number of a flight measurement computer to a source.', 5);
INSERT INTO lessons (course_slug, id, module_id, title, minutes, summary, position) VALUES ('imu-flight-data-acquisition', 'spec-computer', 'm6', 'Capstone: specify a measurement computer for a Phoenix-class rocket', 60, 'A requirement table with the source and margin for every range, rate and size, and a list of what ASRI still has to tell you.', 0);
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 0, 'h', '{"text":"The brief"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 1, 'p', '{"text":"Design the data side of a flight measurement computer for a Phoenix-class hybrid sounding rocket (about 4.5 kN, 12 to 15 s burn, 75° to 85° launch) that also supports a static test of an 18 kN liquid engine. Every number must trace to a source in this course, with the margin stated."}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 2, 'h', '{"text":"Flight IMU"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 3, 'table', '{"head":["Item","Value","Source and margin"],"rows":[["Accelerometer range","±32 g","ASRI peak 9.98 g; margin 3.2; NASA-class Orion is about 20 g"],["Gyro range","±2 000 °/s minimum, roll axis ±4 000 °/s preferred","ASRI 1 080 °/s (margin 1.85); NASA spin up to 7 Hz = 2 520 °/s"],["IMU sample rate","1 kHz","Sample at far above the vehicle''s motion; 13 B per sample on SPI is 1.3 percent of an 8 MHz bus"],["Quaternion update","At the IMU rate","1.08° per step at 1 080 °/s"],["Gyro bias","Measure 30 s at the pad, before arming","A 0.1 °/s bias gives 6° in 60 s"],["Storage","6 ch × 2 B × 1 kHz = 12 kB/s; 10.8 MB for 15 minutes","Not a constraint"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 4, 'h', '{"text":"Vibration channel"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 5, 'table', '{"head":["Item","Value","Source and margin"],"rows":[["Sensor","Analog ±100 g accelerometer on rigid structure, or IEPE","NASA 10 to 12.7 Grms, 3-sigma peaks 30 to 38 g (margin 2.6)"],["Band","20 to 2 000 Hz baseline; 10 kHz optional","NASA test band"],["Sample rate","10 kS/s minimum, 25 kS/s if the 10 kHz option is kept","5 times the 2 kHz band"],["Anti-alias filter","5-pole Butterworth at 2 kHz for fs = 10 kS/s (60 dB at 8 kHz), or oversample at 25 kS/s with a digital filter","Butterworth attenuation formula"],["PSD","4096-point Welch, resolution 2.44 Hz, record at least 12 s","About 19 percent random error for 29 averages"]]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 6, 'h', '{"text":"Computer"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 7, 'ul', '{"items":["**Pre-trigger buffer:** 5 s of IMU data (60 kB) and 2 s of vibration data (300 kB at 25 kS/s).","**Write buffer:** 30 kB for a 200 ms card stall at 150 kB/s.","**Clock:** one hardware counter, GPS pulse-per-second reference, launch marker in the log.","**Power:** 150 mA for a 6 hour hold with margin 1.5 gives 1 350 mAh.","**Telemetry:** a decimated stream (position, rates, battery) at 10 Hz so a lost recorder still leaves the flight.","**Safety:** hardware arm switch, default safe, read-only toward the engine stand and any pyro line."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 8, 'h', '{"text":"Assumptions to challenge"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 9, 'ul', '{"items":["The 4.5 kN, 10 g Phoenix numbers are ASRI''s. A liquid flight vehicle will be different; its thrust-to-weight is not published.","Vibration levels are NASA test levels, not ASRI flight data.","The 200 ms card stall and 150 mA draw are planning values; measure them on the actual hardware."]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 10, 'h', '{"text":"Questions to take to ASRI"}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 11, 'ol', '{"items":["What are STeVe''s thrust, burn time, peak acceleration and roll rate?","Why did the Phoenix-1D roll gyro stop recording at the roll peak?","What are the AIM Xtra''s accelerometer and gyro ranges and logging rate?","Has anyone put an accelerometer on a vehicle or a test stand, and where is that data?","What should be measured first, and on which vehicle?"]}');
INSERT INTO lesson_blocks (course_slug, lesson_id, position, kind, data) VALUES ('imu-flight-data-acquisition', 'spec-computer', 12, 'callout', '{"kind":"key","title":"The first flight data is the best specification","text":"Fly the first version with generous ranges and raw logging, then tighten the next spec with what it records. A computer that records everything at wide margins is a good first instrument."}');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'spec-computer', 0, 'A specification is a table in which every value traces to a source and states its margin.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'spec-computer', 1, 'The ASRI numbers give a ±32 g, ±2 000 to ±4 000 °/s, 1 kHz IMU and a 10 kS/s, ±100 g vibration channel.');
INSERT INTO lesson_takeaways (course_slug, lesson_id, position, text) VALUES ('imu-flight-data-acquisition', 'spec-computer', 2, 'Challenge the assumptions with ASRI data as soon as it exists.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm6', 0, 'What margin does a ±32 g accelerometer give over ASRI''s 9.98 g peak?', '["1.6","2.0","3.2","6.4"]', 2, '32 / 9.98 = 3.2.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm6', 1, 'How many poles give about 60 dB at 8 kHz for a 2 kHz Butterworth cutoff?', '["3","4","5","8"]', 2, '$10\log_{10}(1 + 4^{10}) = 60.2$ dB for five poles.');
INSERT INTO quiz_questions (course_slug, module_id, position, question, options, answer, why) VALUES ('imu-flight-data-acquisition', 'm6', 2, 'What should the first version of the computer log?', '["Only events","Raw data at wide margins","Only filtered attitude","Nothing until launch"]', 1, 'Raw data at wide ranges lets you re-filter after the flight and tighten the next specification.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 0, 'IMU', 'm1', 'Inertial measurement unit: a three-axis accelerometer and a three-axis gyroscope in one package.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 1, 'Full-scale range', 'm1', 'The largest input a sensor reports. Beyond it the output saturates.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 2, 'Margin', 'm1', 'Full-scale range divided by the expected peak.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 3, 'Nyquist frequency', 'm1', 'Half the sample rate; frequencies above it alias.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 4, 'Noise density', 'm2', 'Random noise per root hertz, such as µg/√Hz; rms noise is density times $\sqrt{BW}$.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 5, 'Bias', 'm2', 'Sensor output with zero input. It drifts with temperature and between power-ups.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 6, 'Scale factor', 'm2', 'The gain of a sensor; a scale-factor error mis-reads every value in proportion.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 7, 'Proof mass', 'm2', 'The small suspended mass in a MEMS sensor whose motion is measured.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 8, 'Coriolis effect', 'm2', 'The sideways force on a moving mass in a rotating frame, used to sense rotation in a MEMS gyro.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 9, 'Angle random walk', 'm2', 'Angle error from gyro white noise, growing as the square root of time.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 10, 'Allan variance', 'm2', 'A statistic that separates white noise from slow drift in a long stationary record.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 11, 'g-sensitivity', 'm2', 'Gyro output error caused by acceleration.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 12, 'Body frame', 'm3', 'A coordinate frame fixed to the vehicle; the IMU measures in it.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 13, 'Launch frame', 'm3', 'A coordinate frame fixed to the ground (up, east, north) in which gravity and position are described.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 14, 'Gimbal lock', 'm3', 'The loss of a degree of freedom in Euler angles when pitch reaches 90°.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 15, 'Quaternion', 'm3', 'Four numbers that represent an orientation without singularities.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 16, 'Specific force', 'm3', 'What an accelerometer reports: acceleration minus gravity.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 17, 'Complementary filter', 'm3', 'A blend of a high-passed gyro estimate and a low-passed accelerometer estimate.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 18, 'Kalman filter', 'm3', 'An estimator that tracks a state and its uncertainty, weighting each measurement by its uncertainty.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 19, 'IEPE', 'm4', 'Integrated electronics piezoelectric: a piezo sensor with a built-in amplifier fed by a constant-current line.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 20, 'Grms', 'm4', 'Root-mean-square acceleration in g, the square root of the area under the PSD.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 21, 'Welch''s method', 'm4', 'PSD estimation by averaging windowed FFTs of overlapping segments.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 22, 'Anti-alias filter', 'm4', 'An analog low-pass filter before the ADC that removes content above the Nyquist frequency.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 23, 'Pre-trigger buffer', 'm5', 'A circular buffer that keeps the last few seconds so data before a trigger are not lost.');
INSERT INTO glossary_terms (course_slug, position, term, unit, def) VALUES ('imu-flight-data-acquisition', 24, 'Brown-out', 'm5', 'A supply dip below the safe level; a brown-out detector holds the processor in reset.');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 0, 'Preliminary Results from the 2023 Phoenix Hybrid Rocket Launch Campaign (AIAA 2024-1607)', 'AIAA, UKZN ASRI', 'https://doi.org/10.2514/6.2024-1607', 'Flight data and avionics used in module 1');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 1, 'Development of a Payload Module for the Phoenix-1C Hybrid Sounding Rocket (AIAA 2024-0372)', 'AIAA, UKZN ASRI', 'https://doi.org/10.2514/6.2024-0372', 'The 9.98 g flight measurement');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 2, 'Preliminary Performance Data of an 18 kN Ablatively Cooled, Blowdown Liquid Rocket Engine (AIAA 2024-1397)', 'AIAA, UKZN ASRI', 'https://doi.org/10.2514/6.2024-1397', 'SAFFIRE ABLE test data');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 3, 'Facility Design and Cold Flow Testing for an 18 kN LOX/Kerosene Engine (AIAA 2024-1399)', 'AIAA, UKZN ASRI', 'https://doi.org/10.2514/6.2024-1399', 'Test-facility instrumentation');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 4, 'Sounding Rockets Program Handbook (810-HB-SRP)', 'NASA Wallops', 'https://www.nasa.gov/wp-content/uploads/2023/09/sounding-rocket-program-handbook.pdf', 'Vibration test levels, spin and acceleration');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 5, 'Kalman and Bayesian Filters in Python (Labbe)', 'Open textbook', 'https://github.com/rlabbe/Kalman-and-Bayesian-Filters-in-Python', 'Filters in code');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 6, 'The Scientist and Engineer''s Guide to Digital Signal Processing (Smith)', 'Open textbook', 'https://www.dspguide.com/', 'Sampling, filters and the FFT');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 7, 'Guide to Accelerometer Installation (TP319)', 'Endevco', NULL, 'Study library #23');
INSERT INTO library_refs (course_slug, position, title, org, url, note) VALUES ('imu-flight-data-acquisition', 8, 'Anti-aliasing filter design for a 100 kHz DAQ signal chain (SBAA655)', 'Texas Instruments', NULL, 'Study library #20');
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'phoenix-accel', 'm1', 'Phoenix axial acceleration', 'Phoenix-1C flew at a peak of **9.98 g** axial, against a 10 g payload design limit (ASRI, AIAA 2024-0372).', 0);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'phoenix-roll', 'm1', 'Phoenix roll rate', '**3 Hz (1 080 °/s)** measured on Phoenix-1C, against 0.53 Hz predicted. Predicted powered-flight roll for Phoenix-1D was 2.66 Hz (958 °/s).', 1);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'phoenix-motor', 'm1', 'Phoenix motor', 'About **4.4 to 4.6 kN** for **12 to 15 s** at 26 to 27 bar (PV-3 hybrid, paraffin with 20 percent aluminium and nitrous oxide).', 2);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'able-engine', 'm1', 'SAFFIRE ABLE', 'About **18 kN** at **12 bar**, LOX and Jet A-1 at 5.7 and 2.3 kg/s; tested for up to 66 s.', 3);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'margin', 'm1', 'Range margin', 'margin = full scale / expected peak. Use at least **2**; 3 is comfortable.', 4);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'noise-bw', 'm2', 'Noise from density', '$\sigma = N\sqrt{BW}$. 70 µg/√Hz over 500 Hz is **1.57 mg** rms.', 5);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'gyro-bias', 'm2', 'Gyro bias drift', 'Angle error $= b\,t$. A **0.1 °/s** bias is **6°** in 60 s.', 6);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'six-pos', 'm2', 'Six-position calibration', '$b = (a_+ + a_-)/2$, $s = (a_+ - a_-)/(2g) - 1$.', 7);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'pos-error', 'm3', 'Position error from bias', '$\delta x = \tfrac12 b t^2$. **0.05 m/s²** gives **40 m** in 40 s.', 8);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'gravity-leak', 'm3', 'Gravity leakage', 'A tilt error $\delta\theta$ leaks $g\sin\delta\theta$. **1°** is 0.171 m/s², or **137 m** in 40 s.', 9);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'nasa-vib', 'm4', 'NASA random vibration', 'Level 1: **10.0 Grms** thrust, **7.6 Grms** lateral, 20 to 2 000 Hz. Level 2: **12.7 Grms**. Peaks are about 3 times Grms.', 10);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'butter', 'm4', 'Butterworth attenuation', '$A = 10\log_{10}[1+(f/f_c)^{2n}]$. Five poles give **60 dB** at $4f_c$.', 11);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'welch', 'm4', 'Welch statistics', '$\Delta f = f_s/N_{fft}$; random error $\approx 1/\sqrt{N_{avg}}$.', 12);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'stall', 'm5', 'Write buffer', 'buffer = data rate × worst-case card stall. 150 kB/s for 200 ms is **30 kB**.', 13);
INSERT INTO databank_facts (course_slug, id, unit, title, text, position) VALUES ('imu-flight-data-acquisition', 'battery', 'm5', 'Battery', '$C = I\,t\times$ margin. 150 mA for 6 hours with margin 1.5 is **1 350 mAh**.', 14);
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('imu-flight-data-acquisition', 'py-calibrate', 'm2', 'Six-position and stationary calibration', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('imu-flight-data-acquisition', 'py-complementary', 'm3', 'Quaternion gyro integration and a tilt-trust test', 'python', 'import numpy as np
INSERT INTO databank_code (course_slug, id, unit, title, lang, code, note, position) VALUES ('imu-flight-data-acquisition', 'py-psd', 'm4', 'PSD and Grms from a vibration log', 'python', 'import numpy as np
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('imu-flight-data-acquisition', 'm1-problems', 'm1', 'Ranges and rates', 'Margins, roll rate, sample rate and storage.', 'problems', 0);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm1-problems', 'm1-problems-1', 0, 'numeric', 1, 'A rocket rolls at 3 Hz. What is the roll rate in °/s?', NULL, '$3 \times 360 = 1\,080$ °/s.', NULL, NULL, 1080, 0.02, '°/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm1-problems', 'm1-problems-2', 1, 'numeric', 1, 'What margin does a ±2 000 °/s gyro give over a 1 080 °/s roll rate?', NULL, '$2000/1080 = 1.85$.', NULL, NULL, 1.85, 0.02, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm1-problems', 'm1-problems-3', 2, 'numeric', 1, 'What margin does a ±32 g accelerometer give over a 9.98 g peak?', NULL, '$32/9.98 = 3.21$.', NULL, NULL, 3.2, 0.02, '');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm1-problems', 'm1-problems-4', 3, 'numeric', 2, 'Six 16-bit IMU channels are logged at 1 kHz for 15 minutes. How many megabytes is that?', NULL, '$6 \times 2 \times 1000 \times 900 = 10.8\times10^6$ bytes.', NULL, NULL, 10.8, 0.02, 'MB');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm1-problems', 'm1-problems-5', 4, 'mcq', 1, 'A channel must reach 2 kHz. Which sample rate follows the 2.5 to 5 times rule?', NULL, '2.5 to 5 times 2 kHz is 5 to 10 kS/s.', '["3 kS/s","5 kS/s to 10 kS/s","50 S/s","1 kS/s"]', 1, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('imu-flight-data-acquisition', 'm2-problems', 'm2', 'Sensor problems', 'Noise, bias and calibration.', 'problems', 1);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm2-problems', 'm2-problems-1', 0, 'numeric', 1, 'A 70 µg/√Hz accelerometer is read over a 500 Hz bandwidth. What is its rms noise?', NULL, '$70\times10^{-6}\sqrt{500} = 1.57\times10^{-3}$ g.', NULL, NULL, 1.57, 0.02, 'mg');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm2-problems', 'm2-problems-2', 1, 'numeric', 1, 'A gyro has a 0.1 °/s bias that is never removed. What is the angle error after 60 s?', NULL, '$0.1 \times 60 = 6°$.', NULL, NULL, 6, 0.02, '°');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm2-problems', 'm2-problems-3', 2, 'numeric', 1, 'Six-position readings are +1.02 g and −0.98 g. What is the accelerometer bias?', NULL, '$(1.02 + (-0.98))/2 = 0.02$ g.', NULL, NULL, 0.02, 0.03, 'g');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm2-problems', 'm2-problems-4', 3, 'numeric', 2, 'A gyro with 2.8 m°/s/√Hz noise density runs for 15 s. What angle noise accumulates?', NULL, '$2.8\times10^{-3}\sqrt{15} = 0.0108°$.', NULL, NULL, 0.0108, 0.03, '°');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm2-problems', 'm2-problems-5', 4, 'written', 2, 'Why should gyro bias be measured at the pad, not only on the bench?', NULL, 'Bias changes with temperature and differs at each power-up, so a bench value goes stale. A 30 s stationary record at the pad, taken just before arming, gives the bias at the temperature and state the gyro will fly in. An uncorrected 0.1 °/s bias becomes a 6° attitude error in 60 s.', NULL, NULL, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3', 'Attitude and error growth', 'Quaternion steps, filters and error growth.', 'problems', 2);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3-problems-1', 0, 'numeric', 1, 'A 0.05 m/s² acceleration bias runs for 40 s. What velocity error results?', NULL, '$\delta v = bt = 0.05 \times 40 = 2$ m/s.', NULL, NULL, 2, 0.02, 'm/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3-problems-2', 1, 'numeric', 1, 'The same bias runs for 40 s. What position error results?', NULL, '$\delta x = \tfrac12 b t^2 = 0.5 \times 0.05 \times 1600 = 40$ m.', NULL, NULL, 40, 0.02, 'm');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3-problems-3', 2, 'numeric', 2, 'A 1° tilt error leaks gravity into the horizontal acceleration. How large is the leak?', NULL, '$9.81\sin 1° = 0.171$ m/s².', NULL, NULL, 0.171, 0.02, 'm/s²');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3-problems-4', 3, 'numeric', 2, 'A complementary filter uses $\alpha = 0.98$ and $\Delta t = 10$ ms. What is its time constant?', NULL, '$\tau = \alpha\Delta t/(1-\alpha) = 0.98\times0.01/0.02 = 0.49$ s.', NULL, NULL, 0.49, 0.02, 's');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3-problems-5', 4, 'numeric', 1, 'A gyro reads 1 080 °/s and is sampled at 1 kHz. How many degrees does the attitude advance per sample?', NULL, '$1080 \times 0.001 = 1.08°$.', NULL, NULL, 1.08, 0.02, '°');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm3-problems', 'm3-problems-6', 5, 'mcq', 2, 'During motor burn, why must accelerometer tilt correction be switched off?', NULL, 'The accelerometer reports specific force. During boost that points along the body axis however the rocket is tilted.', '["The accelerometer saturates","It measures thrust along the body axis, which carries no tilt information","Gravity is zero","The gyro is more accurate then"]', 1, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4', 'Vibration and filter problems', 'Grms, PSD statistics and anti-alias filters.', 'problems', 3);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4-problems-1', 0, 'numeric', 1, 'A flat PSD of 0.029 g²/Hz covers 20 to 2 000 Hz. What is the Grms?', NULL, '$\sqrt{0.029\times1980} = 7.58$ g.', NULL, NULL, 7.58, 0.02, 'g');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4-problems-2', 1, 'numeric', 1, 'A random signal has 12.7 Grms. What is the approximate 3-sigma peak?', NULL, '$3 \times 12.7 = 38.1$ g.', NULL, NULL, 38.1, 0.02, 'g');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4-problems-3', 2, 'numeric', 2, 'A Welch PSD uses 50 averages. What is the approximate random error, as a percentage?', NULL, '$1/\sqrt{50} = 0.141$.', NULL, NULL, 14.1, 0.03, '%');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4-problems-4', 3, 'numeric', 1, 'At fs = 10 kS/s and 4096 points, what is the PSD frequency resolution?', NULL, '$f_s/N = 10\,000/4096 = 2.44$ Hz.', NULL, NULL, 2.44, 0.02, 'Hz');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4-problems-5', 4, 'numeric', 2, 'A 4-pole Butterworth filter has $f_c = 2$ kHz. What is its attenuation at 8 kHz?', NULL, '$10\log_{10}(1 + 4^8) = 48.2$ dB.', NULL, NULL, 48.2, 0.02, 'dB');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm4-problems', 'm4-problems-6', 5, 'mcq', 2, 'How many Butterworth poles are needed for 60 dB at 8 kHz with $f_c = 2$ kHz?', NULL, 'Four poles give 48 dB, five give 60.2 dB.', '["3","4","5","6"]', 2, NULL, NULL, NULL);
INSERT INTO practice_packs (course_slug, id, unit, title, blurb, kind, position) VALUES ('imu-flight-data-acquisition', 'm5-problems', 'm5', 'Computer design problems', 'Bus load, buffers and battery.', 'problems', 4);
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm5-problems', 'm5-problems-1', 0, 'numeric', 1, 'An IMU sends 13 bytes per sample at 1 kHz. What bit rate is that, in kbit/s?', NULL, '$13\times8\times1000 = 104$ kbit/s.', NULL, NULL, 104, 0.02, 'kbit/s');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm5-problems', 'm5-problems-2', 1, 'numeric', 2, 'An SD card stalls for 200 ms while data arrive at 150 kB/s. What is the minimum buffer in kB?', NULL, '$150\times0.2 = 30$ kB.', NULL, NULL, 30, 0.02, 'kB');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm5-problems', 'm5-problems-3', 2, 'numeric', 1, 'A computer draws 150 mA and must wait 6 hours on the pad with a 1.5 margin. What battery capacity is needed?', NULL, '$150 \times 6 \times 1.5 = 1\,350$ mAh.', NULL, NULL, 1350, 0.02, 'mAh');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm5-problems', 'm5-problems-4', 3, 'numeric', 2, 'How much memory holds 5 s of six 16-bit channels sampled at 1 kHz?', NULL, '$12 \times 1000 \times 5 = 60\,000$ B.', NULL, NULL, 60, 0.02, 'kB');
INSERT INTO practice_problems (course_slug, pack_id, id, position, kind, difficulty, prompt, hint, solution, options, answer, numeric_value, numeric_tolerance, numeric_unit) VALUES ('imu-flight-data-acquisition', 'm5-problems', 'm5-problems-5', 4, 'written', 2, 'List three lessons from ASRI''s Phoenix flights that should become requirements for a flight computer, and say why each matters.', NULL, 'Power: the Phoenix-1C video battery drained during a long pad hold, so size the battery for the wait or power from the umbilical. Timing: the Phoenix-1D sensors began recording at different times, so use one clock and a pre-trigger buffer. Data loss: the Phoenix-1C recorder stopped before impact, so send a decimated stream by radio. A fourth is sample rate: a combustion-pressure channel set to about 10 samples per second could not be analysed, so verify the rate before the test.', NULL, NULL, NULL, NULL, NULL);
